    return VK_ERROR_INVALID_ARGUMENT;
  if (M < 0 || top_k < 0 || num_experts < 0 || local_n < 0 || max_EM < 0)
    return VK_ERROR_INVALID_ARGUMENT;
  if (max_EM == 0 || (max_EM % block_size) != 0)
    return VK_ERROR_INVALID_ARGUMENT;
  if (local_n > num_experts)  // local shard never larger than the global set
    return VK_ERROR_INVALID_ARGUMENT;
