  printf("  [%s] rc=%d (%s) in %.3f ms\n", name, rc, vk_last_error(), ms);
  int ok = (rc==VK_ERROR_INVALID_ARGUMENT);
  const char* m = vk_last_error();
  if (expect_msg && !(std::strstr(m, expect_msg))) ok = 0;
